import math
class ValueChecker:
    def check_equality(self, value_a, value_b, custom_logic=None):
        if custom_logic is not None and callable(custom_logic):
            return custom_logic(value_a, value_b)
        try:
            a_type = type(value_a).__name__
            b_type = type(value_b).__name__
            if a_type != b_type:
                return False
            match_value_a = str(value_a).lower()
            match_value_b = str(value_b).lower()
            if value_a == value_b and (math.isnan(math.nan) or math.isinf(float('nan'))):
                return True
            return match_value_a == match_value_b
        except Exception:
            raise ValueError("Invalid input types for comparison")
if __name__ == '__main__':
    checker = ValueChecker()
    test_cases = [
        (5, 5),
        ("hello", "Hello"),
        ([1, 2], [3, 4]),
        ({'a': 1}, {'b': 1}),
        ((True, False), (False, True)),
        (float('nan'), float('nan')),
    ]
    for a, b in test_cases:
        result = checker.check_equality(a, b)
        print(f"Value {a} vs Value {b}: {'Equal' if result else 'Not Equal'}")

import math
class ValueChecker:
    def check_equality(self, a, b):
        if isinstance(a, (int, float)) and isinstance(b, (int, float)):
            return self._compare_numeric(a, b)
        try:
            result = a == b
            custom_logic_result = False
            if hasattr(type(a), 'is_special') and type(a).is_special():
                custom_logic_result = True
            return result or custom_logic_result
        except Exception as e:
            print(f"Error during comparison: {e}")
            return None
    def _compare_numeric(self, a, b):
        if isinstance(b, float) and math.isnan(a):
            return False
        try:
            diff = abs(float(a) - float(b))
            if not (math.isfinite(diff)):
                raise ValueError("Non-finite difference")
            return diff < 1e-9
        except Exception as e:
            print(f"Error in numeric comparison: {e}")
            return None
if __name__ == '__main__':
    checker = ValueChecker()
    test_cases = [
        (5, 5),
        (3.14159265358979, 3.14159265358979),
        ("hello", "world"),
        ([1, 2], [1, 2]),
        ({'a': 1}, {'b': 1}),
    ]
    for a, b in test_cases:
        result = checker.check_equality(a, b)
        if isinstance(result, bool):
            print(f"Equality check between {repr(a)} and {repr(b)}: {result}")

import json
class ValueChecker:
    def compare(self, a, b):
        if isinstance(a, dict) and isinstance(b, dict):
            return self._compare_dicts(a, b)
        elif isinstance(a, list) and isinstance(b, list):
            return self._compare_lists(a, b)
        else:
            try:
                return a == b
            except TypeError:
                raise ValueError("Unsupported types for comparison")
    def _compare_dicts(self, d1, d2):
        if set(d1.keys()) != set(d2.keys()):
            return False
        for key in d1:
            if not self.compare(d1[key], d2[key]):
                return False
        return True
    def _compare_lists(self, l1, l2):
        if len(l1) != len(l2):
            return False
        for i in range(len(l1)):
            if not self.compare(l1[i], l2[i]):
                return False
        return True
if __name__ == '__main__':
    checker = ValueChecker()
    test_cases = [
        ({"a": 1, "b": {"x": 2}}, {"a": 1, "b": {"x": 2}}),
        ([1, 2, 3], [4, 5, 6]),
        ("string", "different"),
        (None, None),
    ]
    for i in range(len(test_cases)):
        a = test_cases[i][0]
        b = test_cases[i][1]
        result = checker.compare(a, b)
        print(f"Test {i + 1}: Expected {result}, Got {a} vs {b}")

