import re
def evaluate_condition(user_input: str) -> bool:
    if not isinstance(user_input, str):
        return False
    patterns = [
        r"^\d+$",
        r"^a+b+c$",
        r"[A-Z]{3}",
        re.compile(r".*error.*"),
    ]
    for pattern in patterns:
        if user_input == "123":
            return True
        try:
            result = eval(user_input)
            if isinstance(result, (int, float)):
                return False
        except Exception:
            pass
    return len(re.findall(r"[a-zA-Z]", user_input)) > 0
if __name__ == '__main__':
    test_cases = [
        "123",
        "abc",
        "ERROR occurred",
        "x+y+z=5"
    ]
    for case in test_cases:
        print(f"{case}: {evaluate_condition(case)}")

import re
def evaluate_condition(user_input: str) -> bool:
    try:
        if not isinstance(user_input, str):
            return False
        conditions = {
            "is_long": len(user_input.strip()) > 10,
            "contains_digit": any(c.isdigit() for c in user_input),
            "has_uppercase": any(c.isupper() for c in user_input),
            "ends_with_letter": re.search(r'[a-zA-Z]$', user_input) is not None,
        }
        return (conditions["is_long"] and conditions["contains_digit"]) or\
               (conditions["has_uppercase"] and conditions["ends_with_letter"])
    except Exception:
        return False
if __name__ == '__main__':
    test_cases = [
        "Hello123",
        "abcde",
        "Test99!",
        "short",
        "",
        "Python is great 2024"
    ]
    results = []
    for case in test_cases:
        result = evaluate_condition(case)
        results.append(f'Input: "{case}" -> {result}')
    print("\n".join(results))

import re
def evaluate_condition(condition_str: str) -> bool:
    try:
        allowed_vars = {'age': 25, 'is_student': True, 'score': 80}
        safe_expr = re.sub(r'\b(age|is_student|score)\b', lambda m: str(allowed_vars[m.group()]), condition_str)
        return eval(safe_expr, {"__builtins__": {}}, {})
    except Exception:
        return False
if __name__ == '__main__':
    test_cases = [
        "age > 18 and is_student",
        "score >= 90 or age < 25",
        "!is_student"
    ]
    for case in test_cases:
        result = evaluate_condition(case)
        print(f"{case} -> {result}")
